import{_ as a,o as t,c as r,ag as i}from"./chunks/framework.D7xI0JV8.js";const f=JSON.parse('{"title":"Live Proof Readout","description":"","frontmatter":{},"headers":[],"relativePath":"proof-readout.md","filePath":"proof-readout.md"}'),o={name:"proof-readout.md"};function n(s,e,d,l,c,h){return t(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="live-proof-readout" tabindex="-1">Live Proof Readout <a class="header-anchor" href="#live-proof-readout" aria-label="Permalink to &quot;Live Proof Readout&quot;">​</a></h1><p>This page exists for one purpose: get you to <strong><a href="https://zkde.fi/test" target="_blank" rel="noreferrer">zkde.fi/test</a></strong> with enough context to understand what you&#39;re looking at.</p><p>Every technical claim in these docs — every contract address, every proof lane, every privacy primitive — is verifiable at that endpoint.</p><h2 id="what-zkde-fi-test-shows" tabindex="-1">What zkde.fi/test Shows <a class="header-anchor" href="#what-zkde-fi-test-shows" aria-label="Permalink to &quot;What zkde.fi/test Shows&quot;">​</a></h2><p>The test endpoint runs a full backend showcase that exercises the entire proof pipeline and reports pass/fail status for each claim. It validates <strong>14 independent claims</strong> across:</p><h3 id="modelbridge-dual-lane-proving" tabindex="-1">ModelBridge Dual-Lane Proving <a class="header-anchor" href="#modelbridge-dual-lane-proving" aria-label="Permalink to &quot;ModelBridge Dual-Lane Proving&quot;">​</a></h3><ul><li>EZKL model inference → Groth16 proof generation</li><li>ModelBridge circuit verification via Garaga on Starknet Sepolia</li><li>ModelBridgeHeavy lane with heavier artifact payloads</li><li>STARK integrity lane via Stone prover</li><li>Noir HONK bridge lane</li><li>Native KZG strict lane with bundle injection</li></ul><h3 id="ai-advisory-flow" tabindex="-1">AI Advisory Flow <a class="header-anchor" href="#ai-advisory-flow" aria-label="Permalink to &quot;AI Advisory Flow&quot;">​</a></h3><ul><li>zkML risk scoring and anomaly detection</li><li>13-circuit screening bundle execution</li><li>Pool safety analysis with proof receipts</li><li>Agent skill registration and performance tracking</li></ul><h3 id="privacy-and-settlement" tabindex="-1">Privacy and Settlement <a class="header-anchor" href="#privacy-and-settlement" aria-label="Permalink to &quot;Privacy and Settlement&quot;">​</a></h3><ul><li>Full privacy pool commitment and withdrawal proof generation</li><li>Nullifier and Merkle proof verification</li><li>Privacy tier enforcement (strict / standard / express)</li><li>Madara L3 fact registration</li></ul><h3 id="on-chain-verification" tabindex="-1">On-Chain Verification <a class="header-anchor" href="#on-chain-verification" aria-label="Permalink to &quot;On-Chain Verification&quot;">​</a></h3><ul><li>Contract state reads from deployed verifiers</li><li>Receipt registry lookups</li><li>Reputation tier and FICO-pack proof status</li></ul><h2 id="live-transaction-evidence" tabindex="-1">Live Transaction Evidence <a class="header-anchor" href="#live-transaction-evidence" aria-label="Permalink to &quot;Live Transaction Evidence&quot;">​</a></h2><p>These are real verified transactions on Starknet Sepolia. Click through to Voyager to inspect the proof data independently.</p><table tabindex="0"><thead><tr><th>Lane</th><th>Verifier</th><th>Tx Hash</th></tr></thead><tbody><tr><td>ModelBridge (Groth16/Garaga)</td><td><code>groth16_garaga</code></td><td><a href="https://sepolia.voyager.online/tx/0x2c8ea7551f965f4c73292cd3d00745d088b5572c7154bf6b3746c9f66a0679b" target="_blank" rel="noreferrer">0x2c8ea...679b</a></td></tr><tr><td>ModelBridgeHeavy (Groth16/Garaga)</td><td><code>groth16_garaga</code></td><td><a href="https://sepolia.voyager.online/tx/0x49226ffb495953f1a981020ebb61e8ac462410b750ac672dd21d3f0a8f5b59c" target="_blank" rel="noreferrer">0x49226...b59c</a></td></tr><tr><td>Heavy STARK Reputation</td><td><code>stark_integrity</code></td><td><a href="https://sepolia.voyager.online/tx/0x7249f4a0dc41f12dd5249f4e7284c0f4d392ec69740396d1de4e0f83126739d" target="_blank" rel="noreferrer">0x7249f...739d</a></td></tr><tr><td>Noir HONK Bridge</td><td><code>noir_honk</code></td><td><a href="https://sepolia.voyager.online/tx/0x55f1d6cf06ed5e2deaf90c86479c2f03b27ed631478447d14af808f33963475" target="_blank" rel="noreferrer">0x55f1d...3475</a></td></tr><tr><td>Native KZG Strict</td><td><code>native_kzg</code></td><td><a href="https://sepolia.voyager.online/tx/0x5c9e21abd2119600421872f0baad9988ea7082eec54bacea8657649a8cf5f42" target="_blank" rel="noreferrer">0x5c9e2...5f42</a></td></tr></tbody></table><h2 id="core-verification-contracts" tabindex="-1">Core Verification Contracts <a class="header-anchor" href="#core-verification-contracts" aria-label="Permalink to &quot;Core Verification Contracts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Contract</th><th>Network</th><th>Address</th></tr></thead><tbody><tr><td>ModelBridge Verifier</td><td>Starknet Sepolia</td><td><a href="https://sepolia.voyager.online/contract/0x037c42e8734271aca0c3c1bdf1746d9ccc098ddfd5ee211c94bbb8786fa4626f" target="_blank" rel="noreferrer">0x037c4...626f</a></td></tr><tr><td>ZkmlVerifier (ModelBridge-capable)</td><td>Starknet Sepolia</td><td><a href="https://sepolia.voyager.online/contract/0x068abd64a4a78172a5ee15a30bbe614257d62482f07d3ff7fdb72da5aad08923" target="_blank" rel="noreferrer">0x068ab...8923</a></td></tr><tr><td>GaragaVerifier (BN254)</td><td>Starknet Sepolia</td><td><a href="https://sepolia.voyager.online/contract/0x06d0cb7a48b48c5b6ca70f856d249caccea90f506ad7596a6838502fe3aa6d37" target="_blank" rel="noreferrer">0x06d0c...6d37</a></td></tr><tr><td>Halo2Verifier (EZKL KZG)</td><td>Ethereum Sepolia</td><td><a href="https://sepolia.etherscan.io/address/0xF7b555ca4E54a8c7B9A0DDBFa17341575a852Ab9" target="_blank" rel="noreferrer">0xF7b55...2Ab9</a></td></tr><tr><td>ObsqraFactRegistry</td><td>Starknet Sepolia</td><td><a href="https://sepolia.voyager.online/contract/0x02009ab87f581a0a92f65906ce84664a5cfcb86f7266651f48a04fac3c62faa3" target="_blank" rel="noreferrer">0x02009...faa3</a></td></tr></tbody></table><h2 id="how-to-read-the-report" tabindex="-1">How To Read The Report <a class="header-anchor" href="#how-to-read-the-report" aria-label="Permalink to &quot;How To Read The Report&quot;">​</a></h2><p>The report at <a href="https://zkde.fi/test" target="_blank" rel="noreferrer">zkde.fi/test</a> shows:</p><ol><li><strong>Claim name</strong> — what is being tested (e.g., &quot;ModelBridge dual-lane proof with on-chain verification&quot;)</li><li><strong>Status</strong> — PASS or FAIL, with timing data</li><li><strong>Evidence</strong> — transaction hashes, contract addresses, API response excerpts, proof artifacts</li><li><strong>Chain</strong> — which network the verification happened on</li></ol><p>A fully passing report (14/14) means the entire proof pipeline — from EZKL inference through Garaga verification through Madara settlement — is operational at the time of the run.</p><h2 id="programmatic-access" tabindex="-1">Programmatic Access <a class="header-anchor" href="#programmatic-access" aria-label="Permalink to &quot;Programmatic Access&quot;">​</a></h2><p>The same data is available as JSON:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET https://zkde.fi/test?format=json</span></span></code></pre></div><p>Or run the showcase script directly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/hackathon_backend_showcase.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --base-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8003</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --emit-report</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-report-force</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --judge-mode</span></span></code></pre></div><p>This generates <code>artifacts/hackathon_showcase/latest.html</code> and <code>latest.json</code>.</p><hr><p><strong>Every claim in this submission and these docs is verifiable at <a href="https://zkde.fi/test" target="_blank" rel="noreferrer">zkde.fi/test</a>.</strong></p><p>Next: <a href="/docs/intro.html">The Primitive</a> | <a href="/docs/proof-pipeline.html">Proof Pipeline</a> | <a href="/docs/contracts.html">Deployed Contracts</a></p>`,31)])])}const g=a(o,[["render",n]]);export{f as __pageData,g as default};
